-- 创建农业新闻表
CREATE TABLE IF NOT EXISTS `agricultural_news` (
    `id` INT NOT NULL AUTO_INCREMENT COMMENT '自增主键',
    `news_id` VARCHAR(64) NOT NULL COMMENT '新闻ID（来自API）',
    `title` VARCHAR(500) NOT NULL COMMENT '标题',
    `description` TEXT NULL COMMENT '描述',
    `pic_url` VARCHAR(500) NULL COMMENT '图片URL',
    `source` VARCHAR(100) NULL COMMENT '来源',
    `url` VARCHAR(500) NOT NULL COMMENT '原文链接',
    `ctime` VARCHAR(50) NOT NULL COMMENT '原始时间字符串',
    `pub_date` DATETIME NULL COMMENT '解析后的发布时间',
    `is_top` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '是否置顶',
    `is_active` TINYINT(1) NOT NULL DEFAULT 1 COMMENT '是否有效',
    `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_news_id` (`news_id`),
    KEY `idx_pub_date` (`pub_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='农业新闻表';

